use rvn_core::{Engine,Renderer,renderer::SceneRenderBatch,random::RandomState,types::SpriteState};
use rvn_parser::{Value,Statement,Position,Transition,Hotspot,ParsedProgram};
use std::sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}};
#[derive(Clone,Default)]struct Host{batches:Arc<Mutex<Vec<SceneRenderBatch>>>,reject:Arc<AtomicBool>}
impl Renderer for Host{
 fn validate_scene_batch(&self,_:&SceneRenderBatch)->Result<(),String>{if self.reject.load(Ordering::SeqCst){Err("fixture preflight failure".into())}else{Ok(())}}
 fn publish_scene_batch(&mut self,b:SceneRenderBatch){self.batches.lock().unwrap().push(b);}
 fn supports_accessibility(&self)->bool{true}fn validate_accessibility_speech(&self,_:&rvn_ui::accessibility::SpeechRequest)->Result<(),String>{Ok(())}
 fn supports_composable_motion(&self)->bool{true}fn supports_video(&self)->bool{true}fn supports_layered_characters(&self)->bool{true}fn supports_programmable_ui(&self)->bool{true}
 fn supports_custom_canvas(&self)->bool{true}
 fn update_videos(&mut self,_:&[rvn_core::video::VideoView])->Result<(),String>{Ok(())}fn update_motions(&mut self,_:&[rvn_core::motion::MotionView])->Result<(),String>{Ok(())}fn update_interfaces(&mut self,_:&[rvn_ui::programmable::ScreenView])->Result<(),String>{Ok(())}fn update_layered_characters(&mut self,_:&[rvn_core::composition::LayeredView])->Result<(),String>{Ok(())}
 fn set_background(&mut self,_:&str,_:&Transition){}fn show_sprite(&mut self,_:&str,_:Option<&str>,_:&Position,_:&Transition,_:Option<&SpriteState>){}fn hide_sprite(&mut self,_:&str,_:&Transition,_:&SpriteState){}fn move_sprite(&mut self,_:&str,_:&Position,_:&Transition,_:&SpriteState){}fn show_dialogue(&mut self,_:Option<&str>,_:&str){}fn show_choice(&mut self,_:&[String])->usize{0}fn show_imagemap(&mut self,_:&str,_:Option<&str>,_:&[Hotspot])->usize{0}fn music_play(&mut self,_:&str,_:&Transition,_:Option<&str>){}fn music_stop(&mut self,_:&Transition){}fn music_set_volume(&mut self,_:f32){}fn sfx_play(&mut self,_:&str,_:&Transition){}fn sfx_stop(&mut self,_:&str,_:&Transition){}
}

#[path="private_pcm0370/frame_pcm_host.rs"]mod real_pcm0370;
const STORY:&str=r#"flow.consume_v2("actual_audio","play"){sfx.play("host.wav") with fade(1000)}
"first"
flow.consume_v2("actual_audio","volume"){music.volume("0.4")}
"second""#;
fn actual()->Engine<real_pcm0370::PcmHost>{let p=rvn_parser::parse_program(STORY).unwrap();let mut e=Engine::from_program_with_debugger(p,real_pcm0370::PcmHost::default(),8).unwrap();e.renderer.bind_actual(&e.state,e.instance_id(),e.runtime_epoch()).unwrap();e.step_until_interaction().unwrap();let target=e.audio_playback_views().unwrap()[0].token.target.clone();e.renderer.pull(&target,7).unwrap();record(&mut e);e.advance_dialogue().unwrap();e.step_until_interaction().unwrap();record(&mut e);e}
fn record(e:&mut Engine<real_pcm0370::PcmHost>){let source=e.audio_publication_source().unwrap();let snapshot=e.renderer.capture_audio_checkpoint(&e.state,e.instance_id(),e.runtime_epoch()).unwrap();assert!(e.record_audio_publication(&source,snapshot).unwrap());}
fn wire(e:&Engine<real_pcm0370::PcmHost>)->serde_json::Value{serde_json::json!({"state":e.state,"history":format!("{:?}",e.history.entries()),"epoch":e.runtime_epoch(),"interface":e.interface_epoch(),"publication":e.renderer.publication_count()})}
#[test]fn warming_getter_is_a_pure_clone_of_the_actual_opaque_history_visit(){let e=actual();let source=e.preview_game_audio_rollback_source().unwrap().unwrap();let target=e.audio_playback_views().unwrap()[0].token.target.clone();let before=wire(&e);let debug=e.debug_state_source().unwrap();let cursor=e.renderer.cursor(&target).unwrap();let mut candidate=e.audio_rollback_state_for_warming(&source).unwrap();assert!(candidate.scene_execution.is_none());assert!(candidate.game_audio.is_some());assert_eq!(candidate.music.volume,1.0);assert_eq!(candidate.audio_resource_registry().unwrap().tasks.iter().find_map(|t|t.audio.as_ref()).unwrap().checkpoint.as_ref().unwrap().next_sample,7);candidate.game_audio=None;candidate.vars.insert("preview_only".into(),Value::Int(99));assert_eq!(wire(&e),before);assert!(e.accepts_debug_state_source(&debug));assert!(e.accepts_audio_rollback_source(&source));assert_eq!(e.renderer.cursor(&target).unwrap(),cursor);}
#[test]fn actual_clock_change_after_warming_revokes_getter_and_commit_without_publication(){let mut e=actual();let source=e.preview_game_audio_rollback_source().unwrap().unwrap();let _warming=e.audio_rollback_state_for_warming(&source).unwrap();assert!(e.tick_game_frame(0.125,Default::default()).unwrap().progressed);let before=wire(&e);let debug=e.debug_state_source().unwrap();assert!(!e.accepts_audio_rollback_source(&source));assert!(e.audio_rollback_state_for_warming(&source).is_err());assert!(e.rollback_from_audio_source(&source).is_err());assert_eq!(wire(&e),before);assert!(e.accepts_debug_state_source(&debug));}
#[test]fn another_real_engine_cannot_describe_or_restore_a_foreign_opaque_history_visit(){let original=actual();let source=original.preview_game_audio_rollback_source().unwrap().unwrap();let mut other=actual();assert_ne!(original.instance_id(),other.instance_id());assert_eq!(original.runtime_epoch(),other.runtime_epoch());let before=wire(&other);assert!(other.audio_rollback_state_for_warming(&source).is_err());assert!(other.rollback_from_audio_source(&source).is_err());assert_eq!(wire(&other),before);}
